= e($script) ?>" <?= $ts['build_script']===$script?'selected':'' ?>><?= e($script) ?></option><?php endforeach ?></select></label><label class="field"><span>Betriebssystem für das Script</span><select name="build_os"><?php foreach([''=>'Empfehlung des Scripts','debian'=>'Debian','ubuntu'=>'Ubuntu','alpine'=>'Alpine','centos'=>'CentOS','fedora'=>'Fedora','gentoo'=>'Gentoo','archlinux'=>'Arch Linux'] as $value=>$label): ?><option value="<?= $value ?>" <?= $ts['build_os']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></label><label class="field"><span>OS-Version (leer = Script-Standard)</span><input name="build_version" value="<?= e($ts['build_version']) ?>" maxlength="30" placeholder="z. B. 13 oder 24.04"></label><label class="field"><span>Zusätzliche Einrichtung</span><select name="build_profile"><option value="">Standard / gespeicherte Vorlagenrolle</option><option value="ubuntu-webserver" <?= $ts['build_profile']==='ubuntu-webserver'?'selected':'' ?>>Webserver mit Apache & PHP (Ubuntu)</option></select></label></div><p class="small muted">OS und Version müssen vom gewählten Script unterstützt werden. Benötigt das Script mehr Ressourcen, übernimmt der Bauauftrag diese Mindestwerte in die fertige Vorlage.</p></fieldset><label class="checkbox-field"><input type="checkbox" name="active" <?= $t['active']?'checked':'' ?>><span>Für zugeordnete Kundenpakete freigeben (Volume wird vor dem Speichern per API geprüft)</span></label><button class="button button-teal">Vorlage speichern</button></form></section>
