<?php elseif($section==='dns'):$dns=dns_template_settings(); ?><section class="panel form-panel"><h2>Standard-DNS für neue Domains</h2><form method="post"><?= csrf() ?><input type="hidden" name="action" value="dns_template_save"><label class="field"><span>DNS-Zonenvorlage</span><textarea name="content" rows="22" spellcheck="false" maxlength="20000"><?= e($_POST['content']??$dns['content']) ?></textarea><small>Platzhalter: {domain}, {web_ipv4}, {web_ipv6}, {mail_host}. DKIM wird zuerst pro Maildomain in ISPConfig eingerichtet. Der Shop ersetzt {dkim_selector} und {dkim_public} automatisch durch dessen bestätigten öffentlichen Eintrag; feste DKIM-Schlüssel aus der Vorlage werden nicht veröffentlicht. SOA und Nameserver verwaltet OVH.</small></label><label class="checkbox-field"><input type="checkbox" name="enabled" <?= $dns['enabled']?'checked':'' ?>><span>Nach bezahlter Domainbereitstellung automatisch anwenden. Webspace-Domains müssen demselben Kunden als OVH-Domain zugeordnet sein.</span></label><button class="button button-teal">DNS-Vorlage speichern</button></form><p>Die Veröffentlichung erfolgt über OVH. DNS-Änderungen können bis zu 24 Stunden benötigen.</p></section><section class="panel"><h2>DNS-Aufträge</h2><div class="table-scroll"><table><thead><tr><th>Domain</th><th>Status</th><th>Hinweis</th><th></th></tr></thead><tbody><?php foreach(all('SELECT * FROM shop_dns_jobs ORDER BY order_id DESC LIMIT 100') as $j): ?><tr><td><?= e($j['domain']) ?></td><td><?= e($j['state']) ?></td><td><?= e($j['last_error']??'') ?></td><td><?php if($j['state']==='needs_action'): ?><form method="post"><?= csrf() ?><input type="hidden" name="action" value="dns_job_retry"><input type="hidden" name="order_id" value="<?= (int)$j['order_id'] ?>"><button class="button button-outline button-small">Erneut prüfen</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section><?php endif ?>
